// Generates Poulpy's drawings (mood portraits and poses) for Android and iOS.
//   node design/build-poulpy.mjs          write the generated files
//   node design/build-poulpy.mjs --check  fail if a generated file is out of date (used by CI)
//
// The drawing code is ported from the Poulpy Brand Book (v6) so the apps draw exactly the
// validated sketches. Each drawing is built as SVG, normalised (shapes become paths, text
// becomes stroked lettering), then written as:
//   design/poulpy/<name>.svg                                    reference copy
//   app-android/src/main/res/drawable/poulpy_<name>.xml         Android vector drawable
//   app-ios/CoachPoulpy/Assets.xcassets/Poulpy/<Name>.imageset  iOS vector asset
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const tokens = JSON.parse(readFileSync(join(root, 'design/tokens.json'), 'utf8'))
const banner = 'Generated by design/build-poulpy.mjs. Do not edit by hand.'

// ---------------------------------------------------------------------------
// Drawing, from the brand book

const INK = tokens.color.poulpy.ink, BLUE = tokens.color.poulpy.blue, EMBER = tokens.color.poulpy.ember
const MOODS = {
  proud: { tone: tokens.mood.proud, side: 'blue', face: 'cocky' },
  happy: { tone: tokens.mood.happy, side: 'blue', face: 'happy' },
  recovering: { tone: tokens.mood.recovering, side: 'blue', face: 'calm' },
  annoyed: { tone: tokens.mood.annoyed, side: 'ember', face: 'annoyed' },
  grumpy: { tone: tokens.mood.grumpy, side: 'ember', face: 'grumpy' },
  fuming: { tone: tokens.mood.fuming, side: 'ember', face: 'fuming' },
}

const s = (d, w, c) => `<path d="${d}" fill="none" stroke="${c || INK}" stroke-width="${w || 4.5}" stroke-linecap="round" stroke-linejoin="round"/>`
const f = (d, c) => `<path d="${d}" fill="${c || INK}"/>`
const eye = (x, y, rx, ry, hx) => `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${INK}"/><circle cx="${x + (hx ?? -3)}" cy="${y - 4}" r="2.8" fill="#fff"/>`
const EYES = eye(80, 96, 9, 10.5) + eye(120, 96, 9, 10.5)
const blushB = () => '<ellipse cx="64" cy="112" rx="8" ry="4.5" fill="#F49A6B" opacity=".75"/><ellipse cx="136" cy="112" rx="8" ry="4.5" fill="#F49A6B" opacity=".75"/>'
const blushE = () => '<ellipse cx="64" cy="114" rx="8" ry="4.5" fill="#8E2414" opacity=".35"/><ellipse cx="136" cy="114" rx="8" ry="4.5" fill="#8E2414" opacity=".35"/>'
function drop(x, y, k, c) {
  k = k || 1
  return `<path d="M${x} ${y - 9 * k} C${x + 6 * k} ${y - 2 * k} ${x + 6 * k} ${y + 5 * k} ${x} ${y + 5 * k} C${x - 6 * k} ${y + 5 * k} ${x - 6 * k} ${y - 2 * k} ${x} ${y - 9 * k} Z" fill="${c || '#A8DDF7'}" stroke="#3AA6E0" stroke-width="1.5"/>`
}
function spark(x, y, r, c) {
  return `<path d="M${x} ${y - r} L${x + r * 0.3} ${y - r * 0.3} L${x + r} ${y} L${x + r * 0.3} ${y + r * 0.3} L${x} ${y + r} L${x - r * 0.3} ${y + r * 0.3} L${x - r} ${y} L${x - r * 0.3} ${y - r * 0.3} Z" fill="${c || '#F0B53A'}"/>`
}

const FACES = {
  happy: EYES + s('M90 112 Q100 123 110 112') + blushB(),
  calm: s('M71 97 Q80 90 89 97', 4.5) + s('M111 97 Q120 90 129 97', 4.5) + s('M92 113 Q100 119 108 113', 4) + blushB(),
  cocky: f('M71 97 a9 9 0 0 0 18 0 Z') + s('M68 95 L92 93', 4) + eye(120, 96, 9, 10.5) + s('M109 79 Q120 70 132 77', 4.5) + s('M88 114 Q102 123 115 108', 4.5) + blushB(),
  proud: s('M70 99 Q80 86 90 99') + s('M110 99 Q120 86 130 99') + f('M87 109 Q100 132 113 109 Z') + blushB(),
  tired: f('M71 97 a9 9 0 0 0 18 0 Z') + f('M111 97 a9 9 0 0 0 18 0 Z') + s('M69 98 L91 95', 4) + s('M109 95 L131 98', 4) +
    s('M73 110 Q80 114 87 110', 2.5, '#4B6274') + s('M113 110 Q120 114 127 110', 2.5, '#4B6274') +
    `<ellipse cx="100" cy="121" rx="8" ry="6.5" fill="${INK}"/><ellipse cx="100" cy="125" rx="5" ry="2.6" fill="#F07A7A"/>`,
  hurt: eye(80, 97, 9, 10.5) + eye(120, 97, 9, 10.5) + '<circle cx="84" cy="101" r="2" fill="#fff"/><circle cx="124" cy="101" r="2" fill="#fff"/>' +
    s('M68 82 Q78 76 88 80', 4) + s('M132 82 Q122 76 112 80', 4) + s('M91 117 q3 -3 6 0 t6 0 t6 0', 3.5) + blushB(),
  annoyed: f('M71 97 a9 9 0 0 0 18 0 Z') + f('M111 97 a9 9 0 0 0 18 0 Z') + s('M69 96 L91 96', 4) + s('M109 96 L131 96', 4) + s('M110 82 L130 78', 4) + s('M91 116 L109 116', 4.5) + blushE(),
  grumpy: eye(80, 98, 8.5, 9) + eye(120, 98, 8.5, 9) + s('M66 80 L92 89', 5) + s('M134 80 L108 89', 5) + s('M89 121 Q100 110 111 121') + blushE(),
  fuming: eye(81, 100, 7, 7.5) + eye(119, 100, 7, 7.5) + s('M64 82 L93 93', 5.5) + s('M136 82 L107 93', 5.5) +
    `<rect x="86" y="111" width="28" height="13" rx="5" fill="#fff" stroke="${INK}" stroke-width="3.5"/>` + s('M86 117.5 L114 117.5', 2.5) + s('M95 111 L95 124', 2) + s('M105 111 L105 124', 2) + blushE(),
  lift: s('M70 90 L87 96 L70 102', 4.5) + s('M130 90 L113 96 L130 102', 4.5) +
    `<rect x="87" y="110" width="26" height="12" rx="5" fill="#fff" stroke="${INK}" stroke-width="3.5"/>` + s('M87 116 L113 116', 2.5) + blushB(),
  crossed: eye(84, 94, 8.5, 9.5, -5) + eye(124, 94, 8.5, 9.5, -5) + s('M68 79 L92 85', 5) + s('M134 76 L110 85', 5) + s('M90 110 Q98 104 106 110', 4.5) + blushE(),
}

function armsSkirt(fill, dy) {
  const xs = [[26, 126, 25, 17], [62, 139, 24, 18], [100, 143, 24, 18], [138, 139, 24, 18], [174, 126, 25, 17]]
  return xs.map((a) => `<ellipse cx="${a[0]}" cy="${a[1] + dy}" rx="${a[2]}" ry="${a[3]}" fill="${fill}"/>`).join('')
}
const isEmber = (tone) => Object.values(MOODS).some((m) => m.tone === tone && m.side === 'ember')
const lining = (tone) => (isEmber(tone) ? BLUE : EMBER)
const HEAD = 'M37 130 C33 68 64 30 100 30 C136 30 167 68 163 130 Z'
const SHINE = '<ellipse cx="76" cy="56" rx="17" ry="9" fill="#fff" opacity=".22" transform="rotate(-20 76 56)"/>'
const body = (tone) => armsSkirt(lining(tone), 6) + armsSkirt(tone, 0) + `<path d="${HEAD}" fill="${tone}"/>` + SHINE
const dumbbell = (x, y) => `<rect x="${x - 16}" y="${y - 2.5}" width="32" height="5" rx="2.5" fill="#56687A"/><rect x="${x - 22}" y="${y - 11}" width="9" height="22" rx="3" fill="${INK}"/><rect x="${x + 13}" y="${y - 11}" width="9" height="22" rx="3" fill="${INK}"/>`
const text = (x, y, size, fill, value, anchor) => `<text x="${x}" y="${y}" font-size="${size}" fill="${fill}"${anchor ? ` text-anchor="${anchor}"` : ''}>${value}</text>`

const portrait = (mood) => body(MOODS[mood].tone) + FACES[MOODS[mood].face]

const POSES = {
  cocky: () => {
    const t = MOODS.proud.tone
    return '<circle cx="100" cy="90" r="96" fill="#F0B53A" opacity=".12"/>' + body(t) + FACES.cocky +
      spark(6, 52, 10) + spark(196, 40, 8) + spark(176, 4, 5) + spark(24, 10, 5) +
      `<rect x="128" y="-12" width="54" height="24" rx="12" fill="${INK}"/>` + text(155, 5, 14, '#F0B53A', 'PR!', 'middle')
  },
  straining: () => body(MOODS.happy.tone) + FACES.lift + drop(152, 50, 0.9) + drop(46, 64, 0.7) +
    s('M12 70 l-12 -4 M10 86 l-14 0', 3, '#56687A') + s('M188 70 l12 -4 M190 86 l14 0', 3, '#56687A') +
    `<g transform="rotate(-8 196 156)">${dumbbell(196, 156)}</g>`,
  champion: () => {
    const conf = [[-8, 40, '#F0B53A', 20], [20, 0, EMBER, -30], [180, 4, '#5BBEF0', 40], [204, 50, '#F0B53A', -15], [150, -14, EMBER, 10], [46, -12, '#5BBEF0', 60], [100, -24, '#F0B53A', 30]]
      .map((c) => `<rect x="${c[0]}" y="${c[1]}" width="9" height="5" rx="1.5" fill="${c[2]}" transform="rotate(${c[3]} ${c[0]} ${c[1]})"/>`).join('')
    return conf + body(MOODS.proud.tone) + FACES.proud +
      s('M74 120 L96 146', 7, EMBER) + s('M126 120 L104 146', 7, EMBER) +
      '<circle cx="100" cy="152" r="14" fill="#F0B53A" stroke="#C98A0C" stroke-width="3"/>' + spark(100, 152, 7, '#FFF3C4')
  },
  standingTall: () => {
    const t = MOODS.proud.tone
    return `<ellipse cx="100" cy="172" rx="88" ry="6" fill="${INK}" opacity=".1"/>` +
      `<g transform="translate(0 -12)"><g transform="translate(0 -36) scale(1 1.3)">${armsSkirt(lining(t), 6)}${armsSkirt(t, 0)}</g>` +
      `<path d="${HEAD}" fill="${t}"/>${SHINE}${FACES.proud}</g>` +
      s('M-4 70 l0 -16 M-10 60 l6 -6 6 6', 3, '#56687A') + s('M204 70 l0 -16 M198 60 l6 -6 6 6', 3, '#56687A')
  },
  exhausted: () => body(MOODS.recovering.tone) +
    `<path d="M45 60 Q100 38 155 60 L158 76 Q100 54 42 76 Z" fill="#FFFFFF" stroke="${INK}" stroke-opacity=".25" stroke-width="1.5"/>` +
    s('M44 68 Q100 46 156 68', 4, EMBER) +
    s('M157 66 q16 0 22 12', 6, '#FFFFFF') + s('M157 70 q10 10 6 22', 6, '#FFFFFF') +
    FACES.tired + drop(30, 76, 1.1) + drop(172, 88, 1) + drop(160, 112, 0.7) + drop(12, 128, 0.8) + drop(194, 140, 0.9),
  sideGlance: () => {
    const face = f('M89 99 a8.5 8.5 0 0 0 17 0 Z') + f('M124 98 a6.5 7.5 0 0 0 13 0 Z') + s('M87 98 L108 96', 3.5) + s('M122 96 L139 97', 3.5) +
      s('M108 117 Q115 120 122 117', 4) + '<ellipse cx="86" cy="112" rx="7" ry="4" fill="#F49A6B" opacity=".7"/><ellipse cx="144" cy="111" rx="5" ry="3.5" fill="#F49A6B" opacity=".7"/>'
    return `<g transform="rotate(-6 100 140)">${body(MOODS.recovering.tone)}<path d="M70 40 Q56 86 62 128" fill="none" stroke="#fff" stroke-opacity=".25" stroke-width="2"/>${face}</g>` +
      text(160, 40, 22, '#56687A', '…')
  },
  sleeping: () => body(MOODS.recovering.tone) +
    '<path d="M62 52 Q100 30 140 46 C132 26 120 10 108 -4 C96 12 78 30 62 52 Z" fill="#1574B0"/>' + s('M62 52 Q100 32 140 46', 8, '#FFFFFF') + '<circle cx="108" cy="-6" r="8" fill="#FFFFFF" stroke="#B6C4D0" stroke-width="1.5"/>' +
    s('M71 96 Q80 104 89 96') + s('M111 96 Q120 104 129 96') + `<circle cx="100" cy="117" r="4" fill="${INK}"/>` + blushB() +
    text(160, 70, 24, '#1574B0', 'z') + text(178, 52, 17, '#1574B0', 'z'),
  patchedUp: () => body(MOODS.recovering.tone) +
    '<g transform="rotate(35 132 56)"><rect x="112" y="50" width="40" height="13" rx="5" fill="#F5D7B5" stroke="#D9B48C" stroke-width="1.5"/></g>' +
    '<g transform="rotate(-35 132 56)"><rect x="112" y="50" width="40" height="13" rx="5" fill="#F5D7B5" stroke="#D9B48C" stroke-width="1.5"/></g>' +
    FACES.hurt + drop(66, 112, 0.55),
  shy: () => body(MOODS.happy.tone) + s('M70 100 Q80 92 90 100', 4.5) + s('M110 100 Q120 92 130 100', 4.5) + s('M93 116 Q100 121 107 116', 4) +
    '<ellipse cx="66" cy="112" rx="12" ry="6" fill="#F49A6B" opacity=".9"/><ellipse cx="134" cy="112" rx="12" ry="6" fill="#F49A6B" opacity=".9"/>' +
    s('M60 110 l4 4 M66 109 l4 4 M128 109 l4 4 M134 110 l4 4', 2, '#C96A3E') + drop(150, 62, 0.7),
  thinking: () => body(MOODS.happy.tone) + eye(80, 97, 8, 9.5, 0) + eye(120, 95, 9.5, 11, 0) + s('M66 84 L90 86', 4) + s('M110 78 Q120 70 132 76', 4) +
    s('M90 116 q5 -4 10 0 t10 0', 4) + blushB() +
    '<circle cx="160" cy="44" r="4" fill="#B6C4D0"/><circle cx="172" cy="28" r="6" fill="#B6C4D0"/>' +
    '<ellipse cx="196" cy="-4" rx="24" ry="18" fill="#FFFFFF" stroke="#B6C4D0" stroke-width="2"/>' +
    text(196, 6, 26, '#1574B0', '?', 'middle'),
  pouting: () => body(MOODS.grumpy.tone) + FACES.crossed +
    s('M196 150 q6 -6 12 0', 3, '#7A2C12') + s('M200 140 q8 -8 16 0', 3, '#7A2C12') +
    text(-16, 34, 22, '#7A2C12', 'hmph'),
  fuming: () => {
    const puff = (x, y) => [[0, 0, 12], [13, -6, 10], [-12, -4, 9], [3, -15, 9]].map((p) => `<circle cx="${x + p[0]}" cy="${y + p[1]}" r="${p[2]}" fill="#E6EEF4" stroke="#B6C4D0" stroke-width="1.5"/>`).join('')
    return puff(52, 6) + puff(150, -2) + s('M70 30 L64 18', 4, '#B6C4D0') + s('M132 28 L140 14', 4, '#B6C4D0') +
      body(MOODS.fuming.tone) +
      s('M14 80 l-12 -4 M12 96 l-14 0', 3, '#7A2C12') + s('M186 80 l12 -4 M188 96 l14 0', 3, '#7A2C12') +
      FACES.fuming +
      s('M140 50 q6 6 0 12 M152 50 q-6 6 0 12 M140 50 q6 -6 12 0 M140 62 q6 6 12 0', 3.5, '#FFDCC7')
  },
}

// The loading animation: Poulpy seen from above as a blue outline, eight big round lobes each
// ending in a short tail that dips inward. The apps turn it clockwise, so the top moves left to
// right. Small loaders get a thicker line.
const LOADER_PATH = 'M73.7 36.4A26.4 26.4 0 1 1 126.3 36.4A26.4 26.4 0 0 1 122.4 52.3M126.3 36.4A26.4 26.4 0 1 1 163.6 73.7A26.4 26.4 0 0 1 149.6 82.1' +
  'M163.6 73.7A26.4 26.4 0 1 1 163.6 126.3A26.4 26.4 0 0 1 147.7 122.4M163.6 126.3A26.4 26.4 0 1 1 126.3 163.6A26.4 26.4 0 0 1 117.9 149.6' +
  'M126.3 163.6A26.4 26.4 0 1 1 73.7 163.6A26.4 26.4 0 0 1 77.6 147.7M73.7 163.6A26.4 26.4 0 1 1 36.4 126.3A26.4 26.4 0 0 1 50.4 117.9' +
  'M36.4 126.3A26.4 26.4 0 1 1 36.4 73.7A26.4 26.4 0 0 1 52.3 77.6M36.4 73.7A26.4 26.4 0 1 1 73.7 36.4A26.4 26.4 0 0 1 82.1 50.4'
const loader = (width) => s(LOADER_PATH, width, BLUE)

// Portraits and poses share one frame, so they line up when swapped. The loader is square.
const POSE_VIEW = { x: -24, y: -36, width: 248, height: 226 }
const LOADER_VIEW = { x: 0, y: 0, width: 200, height: 200 }
const DRAWINGS = [
  ...Object.keys(MOODS).map((mood) => ({ name: `mood_${snake(mood)}`, svg: portrait(mood), view: POSE_VIEW })),
  ...Object.entries(POSES).map(([pose, draw]) => ({ name: `pose_${snake(pose)}`, svg: draw(), view: POSE_VIEW })),
  { name: 'loader', svg: loader(7), view: LOADER_VIEW },
  { name: 'loader_small', svg: loader(10), view: LOADER_VIEW },
]

function snake(name) { return name.replace(/[A-Z]/g, (c) => '_' + c.toLowerCase()) }
function pascalOf(name) { return name.split('_').map((p) => p.charAt(0).toUpperCase() + p.slice(1)).join('') }

// ---------------------------------------------------------------------------
// Normalising: parse the SVG fragment into a tree of groups and paths

function parse(fragment) {
  const rootNode = { tag: 'g', attrs: {}, children: [] }
  const stack = [rootNode]
  const re = /<(\/?)(\w+)([^>]*?)(\/?)>|([^<]+)/g
  let m
  while ((m = re.exec(fragment))) {
    const top = stack[stack.length - 1]
    if (m[5] !== undefined) { if (top.tag === 'text') top.value = (top.value || '') + m[5]; continue }
    if (m[1]) { stack.pop(); continue }
    const attrs = {}
    for (const a of m[3].matchAll(/([\w-]+)="([^"]*)"/g)) attrs[a[1]] = a[2]
    const node = { tag: m[2], attrs, children: [] }
    top.children.push(node)
    if (!m[4]) stack.push(node)
  }
  return rootNode
}

const fmt = (n) => { const r = Math.round(n * 100) / 100; return Object.is(r, -0) ? '0' : String(r) }
const color = (c) => {
  if (!c || c === 'none') return null
  const h = c.replace('#', '')
  return '#' + (h.length === 3 ? h.split('').map((x) => x + x).join('') : h).toUpperCase()
}
const ellipsePath = (cx, cy, rx, ry) => `M${fmt(cx - rx)} ${fmt(cy)} a${fmt(rx)} ${fmt(ry)} 0 1 0 ${fmt(2 * rx)} 0 a${fmt(rx)} ${fmt(ry)} 0 1 0 ${fmt(-2 * rx)} 0 Z`
function rectPath(x, y, w, h, r) {
  r = Math.min(r || 0, w / 2, h / 2)
  if (!r) return `M${fmt(x)} ${fmt(y)} h${fmt(w)} v${fmt(h)} h${fmt(-w)} Z`
  return `M${fmt(x + r)} ${fmt(y)} h${fmt(w - 2 * r)} a${fmt(r)} ${fmt(r)} 0 0 1 ${fmt(r)} ${fmt(r)} v${fmt(h - 2 * r)} a${fmt(r)} ${fmt(r)} 0 0 1 ${fmt(-r)} ${fmt(r)} h${fmt(-(w - 2 * r))} a${fmt(r)} ${fmt(r)} 0 0 1 ${fmt(-r)} ${fmt(-r)} v${fmt(-(h - 2 * r))} a${fmt(r)} ${fmt(r)} 0 0 1 ${fmt(r)} ${fmt(-r)} Z`
}

// Rounded stroke lettering for the few words drawn in the poses, on a 1-unit em, baseline at 0.
const GLYPHS = {
  h: { d: 'M0 -0.72 L0 0 M0 -0.3 Q0 -0.5 0.19 -0.5 Q0.38 -0.5 0.38 -0.3 L0.38 0', advance: 0.56 },
  m: { d: 'M0 -0.5 L0 0 M0 -0.32 Q0 -0.5 0.16 -0.5 Q0.3 -0.5 0.3 -0.32 L0.3 0 M0.3 -0.32 Q0.3 -0.5 0.46 -0.5 Q0.6 -0.5 0.6 -0.32 L0.6 0', advance: 0.78 },
  p: { d: 'M0 -0.5 L0 0.24 M0 -0.25 a0.19 0.25 0 1 0 0.38 0 a0.19 0.25 0 1 0 -0.38 0', advance: 0.56 },
  z: { d: 'M0 -0.5 L0.36 -0.5 L0 0 L0.36 0', advance: 0.5 },
  '?': { d: 'M0 -0.56 Q0 -0.76 0.2 -0.76 Q0.4 -0.76 0.4 -0.56 Q0.4 -0.42 0.2 -0.34 L0.2 -0.22 M0.2 -0.02 L0.2 0', advance: 0.44 },
  P: { d: 'M0 0 L0 -0.7 L0.2 -0.7 Q0.4 -0.7 0.4 -0.52 Q0.4 -0.34 0.2 -0.34 L0 -0.34', advance: 0.56 },
  R: { d: 'M0 0 L0 -0.7 L0.2 -0.7 Q0.4 -0.7 0.4 -0.52 Q0.4 -0.34 0.2 -0.34 L0 -0.34 M0.2 -0.34 L0.4 0', advance: 0.58 },
  '!': { d: 'M0 -0.7 L0 -0.24 M0 -0.02 L0 0', advance: 0.16 },
  '…': { d: 'M0 -0.02 L0 0 M0.26 -0.02 L0.26 0 M0.52 -0.02 L0.52 0', advance: 0.64 },
}

function lettering(node) {
  const size = +node.attrs['font-size'], value = node.value.trim()
  // The last glyph's advance includes the gap before a next letter, which centring should ignore.
  const width = [...value].reduce((w, ch) => w + (GLYPHS[ch]?.advance ?? 0), 0) - 0.16
  let x = +node.attrs.x - (node.attrs['text-anchor'] === 'middle' ? (width * size) / 2 : 0)
  const y = +node.attrs.y, parts = []
  for (const ch of value) {
    const glyph = GLYPHS[ch]
    if (!glyph) throw new Error(`No lettering for "${ch}"`)
    parts.push(placeGlyph(glyph.d, x, y, size))
    x += glyph.advance * size
  }
  return { d: parts.join(' '), fill: null, stroke: color(node.attrs.fill), strokeWidth: fmt(size * 0.15), cap: 'round', join: 'round' }
}

function placeGlyph(d, ox, oy, k) {
  return d.replace(/([MLQa])([^MLQa]*)/g, (_, cmd, args) => {
    const n = args.trim().split(/\s+/).map(Number)
    if (cmd === 'a') return `a${fmt(n[0] * k)} ${fmt(n[1] * k)} ${n[2]} ${n[3]} ${n[4]} ${fmt(n[5] * k)} ${fmt(n[6] * k)} `
    return cmd + n.map((v, i) => fmt(i % 2 === 0 ? ox + v * k : oy + v * k)).join(' ') + ' '
  }).trim()
}

function transforms(value) {
  if (!value) return []
  return [...value.matchAll(/(\w+)\(([^)]*)\)/g)].map((t) => ({ op: t[1], args: t[2].trim().split(/[\s,]+/).map(Number) }))
}

// A node becomes { transforms, children } groups and { d, fill, stroke, ... } paths.
function normalise(node) {
  const a = node.attrs
  let item
  switch (node.tag) {
    case 'g': item = { group: true, children: node.children.map(normalise) }; break
    case 'text': item = lettering(node); break
    case 'path': item = { d: a.d }; break
    case 'ellipse': item = { d: ellipsePath(+a.cx, +a.cy, +a.rx, +a.ry) }; break
    case 'circle': item = { d: ellipsePath(+a.cx, +a.cy, +a.r, +a.r) }; break
    case 'rect': item = { d: rectPath(+a.x, +a.y, +a.width, +a.height, +(a.rx || 0)) }; break
    default: throw new Error(`Unsupported element <${node.tag}>`)
  }
  if (!item.group && node.tag !== 'text') {
    const opacity = a.opacity !== undefined ? +a.opacity : 1
    Object.assign(item, {
      fill: color(a.fill ?? '#000'),
      fillAlpha: opacity * (a['fill-opacity'] !== undefined ? +a['fill-opacity'] : 1),
      stroke: color(a.stroke),
      strokeAlpha: opacity * (a['stroke-opacity'] !== undefined ? +a['stroke-opacity'] : 1),
      strokeWidth: a['stroke-width'],
      cap: a['stroke-linecap'],
      join: a['stroke-linejoin'],
    })
  }
  const t = transforms(a.transform)
  return t.length ? { group: true, transforms: t, children: [item] } : item
}

// ---------------------------------------------------------------------------
// Writers

function svgOut(tree, VIEW) {
  const walk = (n, pad) => {
    if (n.group) {
      const t = (n.transforms || []).map((x) => `${x.op}(${x.args.join(' ')})`).join(' ')
      const inner = n.children.map((c) => walk(c, pad + '  ')).join('\n')
      return t ? `${pad}<g transform="${t}">\n${inner}\n${pad}</g>` : inner
    }
    const attrs = [`d="${n.d}"`, `fill="${n.fill || 'none'}"`]
    if (n.fill && n.fillAlpha !== undefined && n.fillAlpha !== 1) attrs.push(`fill-opacity="${fmt(n.fillAlpha)}"`)
    if (n.stroke) {
      attrs.push(`stroke="${n.stroke}"`, `stroke-width="${n.strokeWidth || 1}"`)
      if (n.strokeAlpha !== undefined && n.strokeAlpha !== 1) attrs.push(`stroke-opacity="${fmt(n.strokeAlpha)}"`)
      if (n.cap) attrs.push(`stroke-linecap="${n.cap}"`)
      if (n.join) attrs.push(`stroke-linejoin="${n.join}"`)
    }
    return `${pad}<path ${attrs.join(' ')}/>`
  }
  return [
    `<!-- ${banner} -->`,
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${VIEW.x} ${VIEW.y} ${VIEW.width} ${VIEW.height}" width="${VIEW.width}" height="${VIEW.height}">`,
    walk(tree, '  '),
    '</svg>',
    '',
  ].join('\n')
}

function vectorOut(tree, VIEW) {
  const walk = (n, pad) => {
    if (n.group) {
      let open = '', close = '', inner = pad
      for (const t of n.transforms || []) {
        let attrs
        if (t.op === 'translate') attrs = `android:translateX="${fmt(t.args[0])}" android:translateY="${fmt(t.args[1] || 0)}"`
        else if (t.op === 'rotate') attrs = `android:rotation="${fmt(t.args[0])}" android:pivotX="${fmt(t.args[1] || 0)}" android:pivotY="${fmt(t.args[2] || 0)}"`
        else if (t.op === 'scale') attrs = `android:scaleX="${fmt(t.args[0])}" android:scaleY="${fmt(t.args[1] ?? t.args[0])}"`
        else throw new Error(`Unsupported transform ${t.op}`)
        open += `${inner}<group ${attrs}>\n`
        close = `\n${inner}</group>` + close
        inner += '    '
      }
      return open + n.children.map((c) => walk(c, inner)).join('\n') + close
    }
    const attrs = [`android:pathData="${n.d}"`]
    if (n.fill) {
      attrs.push(`android:fillColor="${n.fill}"`)
      if (n.fillAlpha !== undefined && n.fillAlpha !== 1) attrs.push(`android:fillAlpha="${fmt(n.fillAlpha)}"`)
    }
    if (n.stroke) {
      attrs.push(`android:strokeColor="${n.stroke}"`, `android:strokeWidth="${n.strokeWidth || 1}"`)
      if (n.strokeAlpha !== undefined && n.strokeAlpha !== 1) attrs.push(`android:strokeAlpha="${fmt(n.strokeAlpha)}"`)
      if (n.cap) attrs.push(`android:strokeLineCap="${n.cap}"`)
      if (n.join) attrs.push(`android:strokeLineJoin="${n.join}"`)
    }
    return `${pad}<path\n${attrs.map((x) => `${pad}    ${x}`).join('\n')} />`
  }
  return [
    '<?xml version="1.0" encoding="utf-8"?>',
    `<!-- ${banner} -->`,
    '<vector xmlns:android="http://schemas.android.com/apk/res/android"',
    `    android:width="${VIEW.width}dp"`,
    `    android:height="${VIEW.height}dp"`,
    `    android:viewportWidth="${VIEW.width}"`,
    `    android:viewportHeight="${VIEW.height}">`,
    `    <group android:translateX="${-VIEW.x}" android:translateY="${-VIEW.y}">`,
    walk(tree, '        '),
    '    </group>',
    '</vector>',
    '',
  ].join('\n')
}

const imagesetContents = (file) => JSON.stringify({
  images: [{ filename: file, idiom: 'universal' }],
  info: { author: 'xcode', version: 1 },
  properties: { 'preserves-vector-representation': true },
}, null, 2) + '\n'

const files = {
  'app-ios/CoachPoulpy/Assets.xcassets/Poulpy/Contents.json': JSON.stringify({ info: { author: 'xcode', version: 1 } }, null, 2) + '\n',
}
for (const drawing of DRAWINGS) {
  const tree = normalise(parse(drawing.svg))
  const svg = svgOut(tree, drawing.view)
  const asset = `Poulpy${pascalOf(drawing.name)}`
  files[`design/poulpy/${drawing.name}.svg`] = svg
  files[`app-android/src/main/res/drawable/poulpy_${drawing.name}.xml`] = vectorOut(tree, drawing.view)
  files[`app-ios/CoachPoulpy/Assets.xcassets/Poulpy/${asset}.imageset/${asset}.svg`] = svg
  files[`app-ios/CoachPoulpy/Assets.xcassets/Poulpy/${asset}.imageset/Contents.json`] = imagesetContents(`${asset}.svg`)
}

const check = process.argv.includes('--check')
let stale = 0
for (const [path, content] of Object.entries(files)) {
  const full = join(root, path)
  if (check) {
    if (!existsSync(full) || readFileSync(full, 'utf8') !== content) { console.error(`Out of date: ${path}`); stale++ }
  } else {
    mkdirSync(dirname(full), { recursive: true })
    writeFileSync(full, content)
  }
}
if (stale) { console.error('Run `node design/build-poulpy.mjs` and commit the result.'); process.exit(1) }
console.log(check ? 'Poulpy drawings are up to date.' : `Wrote ${Object.keys(files).length} files.`)
